import app from 'flarum/forum/app';
/**
 * Change a report. Not Model#save: that drops a relationship set to null,
 * and "no one" and "the general queue" are both null.
 */
export function updateReport(report, attributes, relationships = {}) {
  const rels = {};
  for (const [key, model] of Object.entries(relationships)) {
    rels[key] = {
      data: model ? {
        type: model.data.type,
        id: model.id()
      } : null
    };
  }
  return app.request({
    method: 'PATCH',
    url: `${app.forum.attribute('apiUrl')}/docket-reports/${report.id()}`,
    body: {
      data: {
        type: 'docket-reports',
        id: report.id(),
        attributes,
        relationships: rels
      }
    }
  }).then(payload => app.store.pushPayload(payload));
}