import { t } from './t';
export const FRAMES = ['30d', '90d', '12m', 'all'];
const BUCKETS = ['resolved', 'rejected', 'open'];
export const percent = (n, total) => total ? Math.round(n * 100 / total) : 0;

/**
 * A member's record as a reporter, frame by frame: how many reports, and how
 * many of them were resolved, rejected or are still open. Helpers, not
 * components: Mithril has no function components.
 */
export function recordPanel(record) {
  return m("section", {
    className: "DocketRecord",
    "aria-label": t('record.title')
  }, m("div", {
    className: "DocketRecord-frames"
  }, FRAMES.map(frame => frameCell(frame, record[frame]))), m("p", {
    className: "DocketRecord-note"
  }, t('record.note')));
}
function frameCell(frame, counts) {
  return m("div", {
    className: "DocketRecord-frame"
  }, m("div", {
    className: "DocketRecord-label"
  }, t(`record.frame_${frame}`)), m("div", {
    className: "DocketRecord-total"
  }, t('record.total', {
    count: counts.total
  })), m("div", {
    className: "DocketRecord-bar",
    "aria-hidden": "true"
  }, BUCKETS.map(bucket => counts[bucket] ? m("span", {
    className: `DocketRecord-bar--${bucket}`,
    style: {
      width: `${counts[bucket] * 100 / counts.total}%`
    }
  }) : null)), m("ul", {
    className: "DocketRecord-counts"
  }, BUCKETS.map(bucket => m("li", {
    className: `DocketRecord-count DocketRecord-count--${bucket}`
  }, m("span", {
    className: "DocketRecord-dot",
    "aria-hidden": "true"
  }), m("span", {
    className: "DocketRecord-name"
  }, t(`record.${bucket}`)), m("span", {
    className: "DocketRecord-num"
  }, counts[bucket], counts.total ? m("span", {
    className: "DocketRecord-pct"
  }, " \xB7 ", percent(counts[bucket], counts.total), "%") : null)))));
}

/** One line for beside a reporter's name: all time. */
export function recordLine(counts) {
  return t('record.line', {
    count: counts.total,
    resolved: percent(counts.resolved, counts.total),
    rejected: percent(counts.rejected, counts.total)
  });
}